// Keep the checked-in Prisma client compatible with the additive Lead schema
// change when the local Prisma engine cannot be regenerated offline.
config.inlineSchema = config.inlineSchema.replace(
  /(model Lead \{[\s\S]*?\n\s+courseId\s+String[^\n]*\n)/,
  '$1  otherCourse       String?\n'
)
config.inlineSchema = config.inlineSchema.replace(
  /(model Lead \{[\s\S]*?\n\s+otherCourse\s+String\?\n)/,
  '$1  nextFollowUpDate  DateTime?\n'
)

config.compilerWasm = {
      getRuntime: async () => require('./query_compiler_fast_bg.js'),
      getQueryCompilerWasmModule: async () => {
        const { Buffer } = require('node:buffer')
        const { wasm } = require('./query_compiler_fast_bg.wasm-base64.js')
        const queryCompilerWasmFileBytes = Buffer.from(wasm, 'base64')

        return new WebAssembly.Module(queryCompilerWasmFileBytes)
      },
      importName: './query_compiler_fast_bg.js',
    }

const PrismaClient = getPrismaClient(config)
exports.PrismaClient = PrismaClient
Object.assign(exports, Prisma)
